from system import R,A,icons,stroke
import re
from math import sin,cos
from pathlib import Path
B=R/'boards'
def ic(k,s=17):return f'<svg aria-hidden="true" width="{s}" height="{s}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="{stroke}" stroke-linecap="round" stroke-linejoin="round"><path d="{icons[k]}"/></svg>'
def tool(k,label='',sel=False):return f'<span class="tool {"sel" if sel else ""}">{ic(k)}{label}</span>'
def title(a,b):return f'<div class="sectionname">{a}<small>{b}</small></div>'
def prop(a,b):
 direction='rtl' if re.search(r'[\u0600-\u06ff]',b) else 'ltr'
 return f'<div class="prop">{a}<b dir="{direction}">{b}</b></div>'
def tabs(*a):return '<div class="tabs">'+''.join(f'<span>{b}</span>' for b in a)+'</div>'
def wave():return '<svg class="wave" preserveAspectRatio="none" viewBox="0 0 360 26">'+''.join(f'<path stroke="#99aba2" stroke-width="2" d="M{i*4} {13-(a:=1+abs(sin(i*.31)*cos(i*.71))*11):.1f}v{2*a:.1f}"/>' for i in range(90))+'</svg>'
def curve():return '''<div class="curve"><svg viewBox="0 0 210 100" preserveAspectRatio="none"><path d="M10 12H200M10 50H200M10 88H200M10 8V90M105 8V90M200 8V90" fill="none" stroke="#35312a"/><path d="M10 88L64 88M145 12H200" fill="none" stroke="#a9a295"/><path d="M10 88C64 88 145 12 200 12" fill="none" stroke="#d9a52e" stroke-width="3"/><g fill="#f5d77e"><circle cx="64" cy="88" r="3"/><circle cx="145" cy="12" r="3"/><path d="m10 83 5 5-5 5-5-5zm190-76 5 5-5 5-5-5z"/></g></svg></div>'''
def gen(mode):
 en=mode=='desk';tr=lambda a,b:b if en else a;phone=mode=='phone';land=mode=='land';name=tr('خط القمّة','RIDGELINE');project=tr('رحلة الجبل','Mountain journal');sel=tr('العنوان','Title');
 top='<div class="top"><img class="mark" src="../assets/logo/mark-metal.svg"><b>'+project+'</b><span class="auto"></span>'+tool('undo')+tool('redo')+'<span class="cta">'+tr('تصدير','Export')+'</span></div>'
 mon='<div class="mon"><div class="stage"><div class="frame"><div class="title">'+name+'</div></div></div><div class="transport">'+ic('play')+'<span><strong>00:02.400</strong> / 00:06.000</span></div></div>'
 tracks=[('V1','video','Ridge.mp4','vid',0,100),('P1','image',tr('صورة','Still'),'img',47,33),('T1','text',name,'txt',20,60),('A1','audio',wave(),'aud',0,94),('FX','fx',tr('لون','Grade'),'fx',10,52)]
 timeline='<div class="tl"><div class="tlbody"><div class="axis"><span class="tag">SEQ / 01</span><div class="ticks m"><span>00:00</span><span>02</span><span>04</span><span>06</span></div></div>'+''.join(f'<div class="lane"><span class="trackid">{ic(k,12)}{id}</span><div class="strip"><span class="clip {cl}" style="left:{left}%;width:{w}%">{text}</span></div></div>' for id,k,text,cl,left,w in tracks if not(land and id in ['P1','FX']))+'<div class="playline"></div></div></div>'
 rack='<div class="tools">'+''.join(tool(k,s,k=='text') for k,s in [('video',tr('فيديو','Video')),('layers',tr('طبقات','Layers')),('text',tr('نص','Title')),('audio',tr('صوت','Audio')),('fx',tr('مؤثرات','Effects'))])+'</div>'
 props=prop(tr('الموضع','Position'),'X 50% · Y 50%')+prop(tr('التحجيم','Scale'),'110%')+prop(tr('الدوران','Rotation'),'0°')+prop(tr('العتامة','Opacity'),'100%');label=title(sel+' · '+name,'T1 / TXT');
 aside='<aside class="ins">'+label+tabs(tr('تحويل','Transform'),tr('مظهر','Appearance'),tr('حركة','Motion'))+props+(('' if land else '<div class="curvesub">'+title(tr('الاستيفاء','Interpolation'),'K1 → K2')+curve()+'</div>'))+'</aside>'
 side='<aside class="side">'+title(tr('المصادر','Media bin'),'BIN / 01')+'<div class="asset"><img src="../assets/media/ridge.jpg">Ridge.mp4</div>'+('<div class="asset">'+tool('audio','Field.wav')+'</div><div class="asset">'+tool('text',name)+'</div>'+('<div class="slot">Drop files here<br>Link existing media</div>' if en else '') if not land else '')+'</aside>'
 sheet='<div class="sheet"><div class="handle"></div>'+label+tabs('تحويل','مظهر','حركة')+prop('التحجيم · مفتاح محدّد','◇ 110%')+'</div>'
 menu='<div class="menu">MAX EDITOR　 /　 File　　 Edit　　 View　　 Workspace <span class="auto"></span>Editing　 ·　 Docked</div>'
 return ('ltr' if en else 'rtl'),(menu if en else '')+top+'<div class="area">'+('' if phone or land else side)+mon+('' if phone else aside)+'</div>'+timeline+(sheet if phone else '')+rack+('<div class="utility">Selection: T1 • Title　 /　 Keyframe K1 <span>Space　Play　　Ctrl+Z　Undo　　+ / −　Zoom</span></div>' if en else '')
for k in ['phone','land','wide','desk']:
 direction,s=gen(k);(B/f'{k}.html').write_text(f'<!doctype html><html lang="{"en" if k=="desk" else "ar"}" dir="{direction}"><meta charset="utf-8"><title>MAX EDITOR — {k} design study</title><link rel="stylesheet" href="workspace.css"><div class="workspace {k}">{s}</div></html>')
def panel(n,tag,h):return '<div class="pan">'+title(n,tag)+h+'</div>'
def board(k,s):
 (B/f'{k}.html').write_text('''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><link rel="stylesheet" href="workspace.css"><style>.panelBoard{width:1040px;padding:22px;background:#101010}.panels{display:grid;grid-template-columns:1fr 1fr;gap:12px}.pan{padding:18px;border-radius:8px;background:#191919;border:1px solid #35312a}.pan .sectionname{font-size:18px}.meter{direction:ltr;background:#35312a;height:5px;margin:12px 0 17px}.meter i{height:100%;display:block;background:#d9a52e}.padded{padding:10px 0}.cap{font:11px monospace;direction:ltr;text-align:left;color:#b8b2a5;letter-spacing:2px}.em{color:#f5d77e}.scope{margin:8px 0;border:1px solid #d9a52e;background:#211b10;padding:6px}.thumbnails{display:flex;gap:8px}.thumbnails>div{flex:1;padding:7px;border:1px solid #35312a}.thumbnails .picked{border-color:#d9a52e}.diamond{letter-spacing:4px;color:#f5d77e}.pan svg.wave{height:64px;background:#243129}.pan .curve svg{height:160px}.previewstrip{height:58px;background:url(../assets/media/ridge.jpg) center/auto 60px}.meter i{width:42%}</style><div class="panelBoard"><div class="cap">MAX EDITOR &nbsp; / &nbsp; DESIGN STUDY &nbsp; / &nbsp; NOT A LIVE FEATURE</div><div class="panels" style="margin-top:14px">'''+s+'</div></div></html>')
board('motion',panel('حركة العنوان','T1 / SCALE',tabs('المفاتيح','التحويل')+prop('النطاق المرئي','00:01.200 — 00:04.800')+prop('المفتاح K1','00:02.400   ·   110%')+prop('المفتاح K2','00:04.000   ·   125%')+'<div class="scope">'+tool('key','تعديل قيمة المفتاح المحدد')+'</div>'+prop('الإجراءات','إضافة · نقل · حذف · نسخ'))+panel('منحنى الانتقال','K1 → K2',tabs('مخصص','خطي','تثبيت')+curve()+'<div class="m" style="display:flex;justify-content:space-between"><span>02.400</span><span>04.000</span></div><div class="mini">أفقي: الزمن · رأسي: تقدم القيمة بين المفتاحين</div>'))
board('properties',panel('خصائص الفيديو','V1 / TRANSFORM',tabs('تركيب','حركة','مظهر')+prop('النطاق','00:00.000 → 00:06.000')+prop('القص','مثل المصدر')+prop('الدوران','0°')+'<div class="mini">الموضع الحالي لا يغيّر بداية المقطع.</div>')+panel('خصائص العنوان','T1 / TYPE',tabs('نص','مظهر','حركة')+'<div class="scope">خط القمّة</div>'+prop('الخط','Tajawal')+prop('المحاذاة','وسط')+prop('الحجم','32'))+panel('صوت الموقع','A1 / LEVEL',wave()+prop('الشدة','85%')+prop('تلاشٍ دخول / خروج','0.4 s / 0.8 s'))+panel('المظهر','FX / PREVIEW',tabs('مؤثر القطعة','انتقال الوصلة')+'<div class="thumbnails"><div class="picked"><div class="thumbFx"></div>دفء · معاينة</div><div><div class="thumbFx" style="filter:grayscale(1)"></div>أحادي</div></div><small>العينة لا تغيّر المشروع قبل «تطبيق».</small>'))
board('export',panel('١. قبل التصدير','REVIEW',prop('النطاق','00:06.000')+prop('الأبعاد ومعدل الإطار','مثل المصدر')+prop('الصوت','بحسب المصدر')+'<div class="padded"><span class="cta">تصدير نسخة</span></div>')+panel('٢. أثناء التحويل','ACTIVE','<div class="em">جارٍ التصدير · 42%</div><div class="meter"><i></i></div>النسبة للشرح فقط؛ تُقرأ القيمة الحقيقية من المهمة.'+prop('الإجراء المتاح','إلغاء'))+panel('٣. الملف منشور','DONE',prop('الوجهة','Movies/MAX EDITOR')+'<div class="padded">تم حفظ الفيديو. فتح الملف أو مشاركته إذا توفّر معالج مناسب.</div>')+panel('٤. تعذّر النشر','RECOVERY','<div style="color:#e05252">المساحة غير كافية.</div><p>حرّر مساحة ثم أعد المحاولة. المشروع وملف المصدر لم يُستبدلا.</p>'))
def beat(label,num,rng,ch,op,active):return panel(label,num,'<div class="previewstrip"></div><div style="position:relative;height:35px;background:#101010;margin:10px 0"><span class="clip '+('txt' if active else 'img')+'" style="left:'+str(rng[0])+'%;width:'+str(rng[1])+'%">T1　 خط القمّة</span><i style="position:absolute;left:40%;height:100%;border-left:2px solid #f5d77e"></i></div>'+prop(ch,op))
board('beats',beat('لا تحديد','01 / BROWSE',[20,60],'المفتش','أدوات المشروع',False)+beat('تحديد العنوان','02 / SELECT',[20,60],'المفتش','T1 · تحويل',True)+beat('سحب النهاية','03 / DRAFT',[20,48],'مسودة غير محفوظة','04.080 s',True)+beat('تأكيد أو إلغاء','04 / COMMIT',[20,48],'بعد إقرار الحفظ','تم حفظ النطاق',True))
